window.CHAPTER_LOCAL=window.CHAPTER_LOCAL||{};window.CHAPTER_LOCAL["rivendell"]=JSON.parse("{\n  \"id\": \"rivendell\",\n  \"title\": \"К Ривенделлу\",\n  \"roman\": \"IV\",\n  \"startSteps\": 514667,\n  \"startKm\": 386,\n  \"totalKm\": 351,\n  \"totalSteps\": 468000,\n  \"endSteps\": 982667,\n  \"stepMeters\": 0.75,\n  \"source\": {\n    \"file\": \"route-master.xlsx\",\n    \"sha256\": \"a93611798140021a39fda53dedc05cc1a5f2147a375a80e35634f40c52eb5c50\",\n    \"sheet\": \"4. К Ривенделлу\",\n    \"thresholds\": \"global, column I\",\n    \"textColumn\": \"L\",\n    \"versionEvidence\": \"38 populated events; 351 km. Workbook metadata has no version label.\"\n  },\n  \"segments\": [\n    {\n      \"id\": 16,\n      \"from\": \"Заветерь\",\n      \"to\": \"Дикие земли\",\n      \"km\": 70,\n      \"startSteps\": 514667,\n      \"endSteps\": 608000,\n      \"geographicStatus\": \"Проверить\",\n      \"geographicNote\": \"«Дикие земли» — авторское промежуточное название, нужно найти точку на карте.\"\n    },\n    {\n      \"id\": 17,\n      \"from\": \"Дикие земли\",\n      \"to\": \"Последний мост\",\n      \"km\": 74,\n      \"startSteps\": 608000,\n      \"endSteps\": 706667,\n      \"geographicStatus\": \"Черновик\",\n      \"geographicNote\": \"Без утверждённой промежуточной точки расстояние приблизительное.\"\n    },\n    {\n      \"id\": 18,\n      \"from\": \"Последний мост\",\n      \"to\": \"Троллистое плоскогорье\",\n      \"km\": 56,\n      \"startSteps\": 706667,\n      \"endSteps\": 781333,\n      \"geographicStatus\": \"Черновик\",\n      \"geographicNote\": \"Название обозначает область.\"\n    },\n    {\n      \"id\": 19,\n      \"from\": \"Троллистое плоскогорье\",\n      \"to\": \"Каменные тролли\",\n      \"km\": 46,\n      \"startSteps\": 781333,\n      \"endSteps\": 842667,\n      \"geographicStatus\": \"Проверить\",\n      \"geographicNote\": \"Внутри Троллистого плоскогорья; 46 км возможно избыточны.\"\n    },\n    {\n      \"id\": 20,\n      \"from\": \"Каменные тролли\",\n      \"to\": \"Восточные ущелья\",\n      \"km\": 45,\n      \"startSteps\": 842667,\n      \"endSteps\": 902667,\n      \"geographicStatus\": \"Проверить\",\n      \"geographicNote\": \"«Восточные ущелья» — рабочее авторское название.\"\n    },\n    {\n      \"id\": 21,\n      \"from\": \"Восточные ущелья\",\n      \"to\": \"Брод Гремячей\",\n      \"km\": 47,\n      \"startSteps\": 902667,\n      \"endSteps\": 965333,\n      \"geographicStatus\": \"Черновик\",\n      \"geographicNote\": \"Уточнить переходы по ущельям.\"\n    },\n    {\n      \"id\": 22,\n      \"from\": \"Брод Гремячей\",\n      \"to\": \"Ривенделл\",\n      \"km\": 13,\n      \"startSteps\": 965333,\n      \"endSteps\": 982667,\n      \"geographicStatus\": \"Черновик\",\n      \"geographicNote\": \"Переход в долину Имладрис.\"\n    }\n  ],\n  \"events\": [\n    {\n      \"id\": \"rivendell-001\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 1,\n      \"title\": \"Склоны Заветери\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 16,\n      \"from\": \"Заветерь\",\n      \"to\": \"Дикие земли\",\n      \"segmentKm\": 10,\n      \"km\": 396,\n      \"steps\": 528000,\n      \"stepsSincePrevious\": 13333,\n      \"text\": \"За спиной постепенно скрываются руины Заветери, а узкая тропа спускается в дикие, почти безлюдные земли. С каждым поворотом знакомые ориентиры остаются всё дальше позади.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-001.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-001-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"rivendell-002\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 2,\n      \"title\": \"Забытая дорога Арнора\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 16,\n      \"from\": \"Заветерь\",\n      \"to\": \"Дикие земли\",\n      \"segmentKm\": 20,\n      \"km\": 406,\n      \"steps\": 541333,\n      \"stepsSincePrevious\": 13333,\n      \"text\": \"Среди высокой травы выступают уцелевшие камни старой дороги Арнора. На одном из них сохранился почти стёртый знак мастера, напоминающий о давно ушедшем королевстве.\",\n      \"reward\": {\n        \"id\": \"rivendell-002-reward\",\n        \"name\": \"Каменный жетон Севера\",\n        \"kind\": \"Находка\",\n        \"icon\": \"❧\",\n        \"description\": \"\",\n        \"cardText\": \"Находка · Каменный жетон Севера\",\n        \"badgePrompt\": \"Небольшой плоский серо-зелёный жетон из камня с почти стёртым знаком древнего королевства, сколы по кромке.\",\n        \"conditional\": false,\n        \"condition\": null\n      },\n      \"rewardSource\": \"Находка · Каменный жетон Севера\",\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": \"Небольшой плоский серо-зелёный жетон из камня с почти стёртым знаком древнего королевства, сколы по кромке.\",\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-002.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-002-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"rivendell-003\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 3,\n      \"title\": \"Поляна среди кустарников\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 16,\n      \"from\": \"Заветерь\",\n      \"to\": \"Дикие земли\",\n      \"segmentKm\": 30,\n      \"km\": 416,\n      \"steps\": 554667,\n      \"stepsSincePrevious\": 13334,\n      \"text\": \"На небольшой поляне среди кустарников видны следы недавнего привала. Рядом с аккуратно сложенными ветками остался каменный очаг, который можно вновь привести в порядок.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-003.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-003-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"rivendell-004\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 4,\n      \"title\": \"Промежуточный привал\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 16,\n      \"from\": \"Заветерь\",\n      \"to\": \"Дикие земли\",\n      \"segmentKm\": 40,\n      \"km\": 426,\n      \"steps\": 568000,\n      \"stepsSincePrevious\": 13333,\n      \"text\": \"Большой валун прикрывает от холодного ветра небольшую площадку у дороги. Пока путник отдыхает и делит дорожные припасы, над долиной проносится стайка птиц.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-004.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-004-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"rivendell-005\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 5,\n      \"title\": \"Разрушенный сигнальный пост\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 16,\n      \"from\": \"Заветерь\",\n      \"to\": \"Дикие земли\",\n      \"segmentKm\": 50,\n      \"km\": 436,\n      \"steps\": 581333,\n      \"stepsSincePrevious\": 13333,\n      \"text\": \"На гребне холма едва различимы остатки каменного сигнального поста. Отсюда когда-то наверняка замечали чужаков задолго до того, как они приближались к дороге.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Проработать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-005.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-005-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"rivendell-006\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 6,\n      \"title\": \"Укрытие от дождя\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 16,\n      \"from\": \"Заветерь\",\n      \"to\": \"Дикие земли\",\n      \"segmentKm\": 60,\n      \"km\": 446,\n      \"steps\": 594667,\n      \"stepsSincePrevious\": 13334,\n      \"text\": \"Внезапный ливень загоняет путника под широкий каменный навес. Среди старых зарубок в укрытии находится бронзовая застёжка, оставленная кем-то из прежних странников.\",\n      \"reward\": {\n        \"id\": \"rivendell-006-reward\",\n        \"name\": \"Путничья застёжка\",\n        \"kind\": \"Находка\",\n        \"icon\": \"❧\",\n        \"description\": \"\",\n        \"cardText\": \"Находка · Путничья застёжка\",\n        \"badgePrompt\": \"Старая бронзовая застёжка для дорожного плаща, простая дуга с коротким шипом, мягкая коричневая патина.\",\n        \"conditional\": false,\n        \"condition\": null\n      },\n      \"rewardSource\": \"Находка · Путничья застёжка\",\n      \"editorialStatus\": \"Проработать\",\n      \"extendedText\": null,\n      \"badgePrompt\": \"Старая бронзовая застёжка для дорожного плаща, простая дуга с коротким шипом, мягкая коричневая патина.\",\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-006.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-006-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"rivendell-007\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 7,\n      \"title\": \"Дикие земли\",\n      \"type\": \"Локация\",\n      \"segment\": 16,\n      \"from\": \"Заветерь\",\n      \"to\": \"Дикие земли\",\n      \"segmentKm\": 70,\n      \"km\": 456,\n      \"steps\": 608000,\n      \"stepsSincePrevious\": 13333,\n      \"text\": \"В Диких землях тропа теряется в жёсткой траве, и до самого горизонта не видно ни одного дома. Держать путь помогают только дальние холмы и редкие каменные ориентиры.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-007.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-007-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": true\n    },\n    {\n      \"id\": \"rivendell-008\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 8,\n      \"title\": \"Выветренные камни\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 17,\n      \"from\": \"Дикие земли\",\n      \"to\": \"Последний мост\",\n      \"segmentKm\": 10.57,\n      \"km\": 466.57,\n      \"steps\": 622093,\n      \"stepsSincePrevious\": 14093,\n      \"text\": \"Вдоль дороги возвышаются камни, которые ветер за долгие годы превратил в причудливые фигуры. Один из них так похож на молчаливого стража, что невольно хочется оглянуться.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-008.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-008-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"rivendell-009\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 9,\n      \"title\": \"Древняя просека\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 17,\n      \"from\": \"Дикие земли\",\n      \"to\": \"Последний мост\",\n      \"segmentKm\": 21.14,\n      \"km\": 477.14,\n      \"steps\": 636187,\n      \"stepsSincePrevious\": 14094,\n      \"text\": \"Кустарник вдруг расступается, открывая ровную полосу забытой просеки. Из земли местами выглядывают тесаные камни, указывая на древнюю дорогу.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-009.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-009-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"rivendell-010\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 10,\n      \"title\": \"Ночной привал у ручья\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 17,\n      \"from\": \"Дикие земли\",\n      \"to\": \"Последний мост\",\n      \"segmentKm\": 31.71,\n      \"km\": 487.71,\n      \"steps\": 650280,\n      \"stepsSincePrevious\": 14093,\n      \"text\": \"Ночью у ручья слышны лишь журчание воды да перекличка сов. Небольшой привал удаётся устроить в тени кустов, не разжигая заметного издалека огня.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-010.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-010-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"rivendell-011\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 11,\n      \"title\": \"Речные излучины\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 17,\n      \"from\": \"Дикие земли\",\n      \"to\": \"Последний мост\",\n      \"segmentKm\": 42.29,\n      \"km\": 498.29,\n      \"steps\": 664387,\n      \"stepsSincePrevious\": 14107,\n      \"text\": \"Река делает широкие изгибы между низкими травянистыми берегами. Под нависшим корнем мелькает выдра и тут же исчезает в тёмной воде.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-011.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-011-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"rivendell-012\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 12,\n      \"title\": \"Переправа\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 17,\n      \"from\": \"Дикие земли\",\n      \"to\": \"Последний мост\",\n      \"segmentKm\": 52.86,\n      \"km\": 508.86,\n      \"steps\": 678480,\n      \"stepsSincePrevious\": 14093,\n      \"text\": \"После дождей узкая протока стала шире и глубже, но из воды всё ещё выступают крупные камни. По ним можно осторожно перебраться на противоположный берег.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Проработать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-012.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-012-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"rivendell-013\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 13,\n      \"title\": \"Дозорная сова\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 17,\n      \"from\": \"Дикие земли\",\n      \"to\": \"Последний мост\",\n      \"segmentKm\": 63.43,\n      \"km\": 519.43,\n      \"steps\": 692573,\n      \"stepsSincePrevious\": 14093,\n      \"text\": \"На сломанном путевом столбе неподвижно сидит большая сова, пристально наблюдая за дорогой. Чуть поодаль в подсохшей грязи угадываются старые следы колёс.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Проработать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-013.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-013-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"rivendell-014\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 14,\n      \"title\": \"Последний мост\",\n      \"type\": \"Локация\",\n      \"segment\": 17,\n      \"from\": \"Дикие земли\",\n      \"to\": \"Последний мост\",\n      \"segmentKm\": 74,\n      \"km\": 530,\n      \"steps\": 706667,\n      \"stepsSincePrevious\": 14094,\n      \"text\": \"Над Митейтелем наконец показываются каменные арки Последнего моста. Перейдя реку, путешественник оставляет позади одну из последних знакомых переправ на пути к Ривенделлу.\",\n      \"reward\": {\n        \"id\": \"rivendell-014-reward\",\n        \"name\": \"За последним мостом\",\n        \"kind\": \"Достижение\",\n        \"icon\": \"✧\",\n        \"description\": \"\",\n        \"cardText\": \"Достижение · За последним мостом\",\n        \"badgePrompt\": \"Круглый серебристо-бронзовый медальон с рельефом старинной каменной арки над рекой, сдержанный орнамент.\",\n        \"conditional\": false,\n        \"condition\": null\n      },\n      \"rewardSource\": \"Достижение · За последним мостом\",\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": \"Круглый серебристо-бронзовый медальон с рельефом старинной каменной арки над рекой, сдержанный орнамент.\",\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-014.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-014-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": true\n    },\n    {\n      \"id\": \"rivendell-015\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 15,\n      \"title\": \"Тропа за Последним мостом\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 18,\n      \"from\": \"Последний мост\",\n      \"to\": \"Троллистое плоскогорье\",\n      \"segmentKm\": 9.33,\n      \"km\": 539.33,\n      \"steps\": 719107,\n      \"stepsSincePrevious\": 12440,\n      \"text\": \"За Последним мостом старая дорога постепенно исчезает под травой. Некоторое время верное направление подсказывают свежие следы небольшого каравана.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-015.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-015-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"rivendell-016\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 16,\n      \"title\": \"Сосновые холмы\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 18,\n      \"from\": \"Последний мост\",\n      \"to\": \"Троллистое плоскогорье\",\n      \"segmentKm\": 18.67,\n      \"km\": 548.67,\n      \"steps\": 731560,\n      \"stepsSincePrevious\": 12453,\n      \"text\": \"Сосновые холмы встречают густым запахом смолы и прохладной тенью. Среди корней цветут голубоватые цветы, а из глубины леса доносится дробный стук дятла.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-016.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-016-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"rivendell-017\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 17,\n      \"title\": \"Каменные уступы\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 18,\n      \"from\": \"Последний мост\",\n      \"to\": \"Троллистое плоскогорье\",\n      \"segmentKm\": 28,\n      \"km\": 558,\n      \"steps\": 744000,\n      \"stepsSincePrevious\": 12440,\n      \"text\": \"Тропа поднимается по каменным уступам, заставляя осторожно выбирать опору для ног. Наверху открывается небольшая площадка, откуда далеко видна извилистая долина.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-017.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-017-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"rivendell-018\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 18,\n      \"title\": \"След каменотёса\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 18,\n      \"from\": \"Последний мост\",\n      \"to\": \"Троллистое плоскогорье\",\n      \"segmentKm\": 37.33,\n      \"km\": 567.33,\n      \"steps\": 756440,\n      \"stepsSincePrevious\": 12440,\n      \"text\": \"На обломке скалы неожиданно виднеются ровные насечки каменотёса — след забытой работы среди глухих холмов. Необычное клеймо хочется сохранить в дорожных заметках.\",\n      \"reward\": {\n        \"id\": \"rivendell-018-reward\",\n        \"name\": \"Знак каменотёса\",\n        \"kind\": \"Находка\",\n        \"icon\": \"❧\",\n        \"description\": \"\",\n        \"cardText\": \"Находка · Знак каменотёса\",\n        \"badgePrompt\": \"Лист дорожных заметок с аккуратной графитной зарисовкой клейма каменотёса — геометрический знак на каменной кладке.\",\n        \"conditional\": false,\n        \"condition\": null\n      },\n      \"rewardSource\": \"Находка · Знак каменотёса\",\n      \"editorialStatus\": \"Проработать\",\n      \"extendedText\": null,\n      \"badgePrompt\": \"Лист дорожных заметок с аккуратной графитной зарисовкой клейма каменотёса — геометрический знак на каменной кладке.\",\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-018.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-018-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"rivendell-019\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 19,\n      \"title\": \"Тень над плоскогорьем\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 18,\n      \"from\": \"Последний мост\",\n      \"to\": \"Троллистое плоскогорье\",\n      \"segmentKm\": 46.67,\n      \"km\": 576.67,\n      \"steps\": 768893,\n      \"stepsSincePrevious\": 12453,\n      \"text\": \"Над плоскогорьем набегают тяжёлые тучи, и каменные глыбы вытягивают по земле длинные тени. На мгновение кажется, будто между холмами замерли настоящие великаны.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Проработать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-019.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-019-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"rivendell-020\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 20,\n      \"title\": \"Плоскогорье троллей\",\n      \"type\": \"Локация\",\n      \"segment\": 18,\n      \"from\": \"Последний мост\",\n      \"to\": \"Троллистое плоскогорье\",\n      \"segmentKm\": 56,\n      \"km\": 586,\n      \"steps\": 781333,\n      \"stepsSincePrevious\": 12440,\n      \"text\": \"Даже в ясный день Плоскогорье троллей выглядит суровым и неприветливым. Среди нагромождённых камней особенно живо вспоминается история Бильбо о трёх незадачливых троллях.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-020.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-020-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": true\n    },\n    {\n      \"id\": \"rivendell-021\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 21,\n      \"title\": \"Поросшая мхом тропа\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 19,\n      \"from\": \"Троллистое плоскогорье\",\n      \"to\": \"Каменные тролли\",\n      \"segmentKm\": 9.2,\n      \"km\": 595.2,\n      \"steps\": 793600,\n      \"stepsSincePrevious\": 12267,\n      \"text\": \"Под толстым мхом обнаруживается гладкий тёсаный камень. Стоит счистить зелень, и на его поверхности проступает старый дорожный знак.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-021.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-021-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"rivendell-022\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 22,\n      \"title\": \"Обвалившийся овраг\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 19,\n      \"from\": \"Троллистое плоскогорье\",\n      \"to\": \"Каменные тролли\",\n      \"segmentKm\": 18.4,\n      \"km\": 604.4,\n      \"steps\": 805867,\n      \"stepsSincePrevious\": 12267,\n      \"text\": \"Обваленные валуны перегородили путь через узкий овраг. В поисках обхода слышится журчание невидимого ручья за каменной стеной.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-022.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-022-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"rivendell-023\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 23,\n      \"title\": \"Следы старого костра\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 19,\n      \"from\": \"Троллистое плоскогорье\",\n      \"to\": \"Каменные тролли\",\n      \"segmentKm\": 27.6,\n      \"km\": 613.6,\n      \"steps\": 818133,\n      \"stepsSincePrevious\": 12266,\n      \"text\": \"У потухшего кострища лежат почерневшие ветки и забытая жестяная кружка. Кто-то недавно устраивал здесь стоянку, но куда он отправился дальше, неизвестно.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-023.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-023-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"rivendell-024\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 24,\n      \"title\": \"Забытый котёл\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 19,\n      \"from\": \"Троллистое плоскогорье\",\n      \"to\": \"Каменные тролли\",\n      \"segmentKm\": 36.8,\n      \"km\": 622.8,\n      \"steps\": 830400,\n      \"stepsSincePrevious\": 12267,\n      \"text\": \"В скальной расщелине темнеет огромный закопчённый котёл, слишком большой для обычного путника. Такая находка заставляет вспомнить, чьи неуклюжие хозяева могли бродить по этим холмам.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Проработать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-024.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-024-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"rivendell-025\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 25,\n      \"title\": \"Каменные тролли\",\n      \"type\": \"Локация\",\n      \"segment\": 19,\n      \"from\": \"Троллистое плоскогорье\",\n      \"to\": \"Каменные тролли\",\n      \"segmentKm\": 46,\n      \"km\": 632,\n      \"steps\": 842667,\n      \"stepsSincePrevious\": 12267,\n      \"text\": \"Среди валунов стоят три окаменевшие фигуры троллей, которых рассвет застал врасплох. У подножия одного из них поблёскивает грубая железная пуговица невероятного размера.\",\n      \"reward\": {\n        \"id\": \"rivendell-025-reward\",\n        \"name\": \"Троллья пуговица\",\n        \"kind\": \"Находка\",\n        \"icon\": \"❧\",\n        \"description\": \"\",\n        \"cardText\": \"Находка · Троллья пуговица\",\n        \"badgePrompt\": \"Очень крупная грубая железная пуговица с четырьмя отверстиями, ржавчина, царапины и следы долгого пребывания в земле.\",\n        \"conditional\": false,\n        \"condition\": null\n      },\n      \"rewardSource\": \"Находка · Троллья пуговица\",\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": \"Очень крупная грубая железная пуговица с четырьмя отверстиями, ржавчина, царапины и следы долгого пребывания в земле.\",\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-025.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-025-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": true\n    },\n    {\n      \"id\": \"rivendell-026\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 26,\n      \"title\": \"Поворот между скалами\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 20,\n      \"from\": \"Каменные тролли\",\n      \"to\": \"Восточные ущелья\",\n      \"segmentKm\": 9,\n      \"km\": 641,\n      \"steps\": 854667,\n      \"stepsSincePrevious\": 12000,\n      \"text\": \"Тропа неожиданно сворачивает в тесный проход между скалами. На выступе кто-то сложил три маленьких камня, оставив безмолвный указатель дороги.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-026.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-026-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"rivendell-027\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 27,\n      \"title\": \"Тёмное ущелье\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 20,\n      \"from\": \"Каменные тролли\",\n      \"to\": \"Восточные ущелья\",\n      \"segmentKm\": 18,\n      \"km\": 650,\n      \"steps\": 866667,\n      \"stepsSincePrevious\": 12000,\n      \"text\": \"В тёмном ущелье шаги отдаются долгим эхом, а высокие стены почти закрывают небо. В глубокой трещине мелькает слабый свет, но с основной тропы до него не добраться.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-027.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-027-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"rivendell-028\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 28,\n      \"title\": \"Скрытый грот\",\n      \"type\": \"Тайник\",\n      \"segment\": 20,\n      \"from\": \"Каменные тролли\",\n      \"to\": \"Восточные ущелья\",\n      \"segmentKm\": 27,\n      \"km\": 659,\n      \"steps\": 878667,\n      \"stepsSincePrevious\": 12000,\n      \"text\": \"У стены ущелья скрывается узкая расселина, ведущая в прохладный грот. В темноте будто притаился старый гномий тайник — заглянуть внутрь или продолжить путь?\",\n      \"reward\": {\n        \"id\": \"rivendell-028-reward\",\n        \"name\": \"Гномий жетон\",\n        \"kind\": \"Секрет\",\n        \"icon\": \"❧\",\n        \"description\": \"\",\n        \"cardText\": \"Секрет · Гномий жетон\",\n        \"badgePrompt\": \"Тяжёлая восьмиугольная гномья монета из тёмного металла, лаконичное руническое клеймо и потёртые края, без читаемого текста.\",\n        \"conditional\": true,\n        \"condition\": {\n          \"branchId\": \"CAVE-03\",\n          \"requires\": \"completed\"\n        }\n      },\n      \"rewardSource\": \"Секрет · Гномий жетон\",\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": \"Тяжёлая восьмиугольная гномья монета из тёмного металла, лаконичное руническое клеймо и потёртые края, без читаемого текста.\",\n      \"optionalBranch\": {\n        \"id\": \"CAVE-03\",\n        \"enabled\": true,\n        \"triggerEventId\": \"rivendell-028\",\n        \"extraKm\": 4,\n        \"extraSteps\": 5333,\n        \"rewardText\": \"Секрет · «Гномий жетон» — Тяжёлая монета с руническим клеймом из забытого грота.\",\n        \"badgePrompt\": \"Тяжёлая восьмиугольная гномья монета из тёмного металла, лаконичное руническое клеймо и потёртые края, без читаемого текста.\"\n      },\n      \"image\": \"assets/illustrations/rivendell/rivendell-028.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-028-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"rivendell-029\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 29,\n      \"title\": \"Серебряная струйка\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 20,\n      \"from\": \"Каменные тролли\",\n      \"to\": \"Восточные ущелья\",\n      \"segmentKm\": 36,\n      \"km\": 668,\n      \"steps\": 890667,\n      \"stepsSincePrevious\": 12000,\n      \"text\": \"Тонкая серебристая струйка воды сбегает с каменного уступа и исчезает между валунами. В полумраке рядом с ней угадываются следы давнего привала.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Проработать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-029.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-029-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"rivendell-030\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 30,\n      \"title\": \"Восточные ущелья\",\n      \"type\": \"Локация\",\n      \"segment\": 20,\n      \"from\": \"Каменные тролли\",\n      \"to\": \"Восточные ущелья\",\n      \"segmentKm\": 45,\n      \"km\": 677,\n      \"steps\": 902667,\n      \"stepsSincePrevious\": 12000,\n      \"text\": \"Стены Восточных ущелий постепенно расходятся, и вместо тесных каменных проходов впереди открывается широкая долина. На её дальнем краю уже зеленеют лесистые склоны.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-030.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-030-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": true\n    },\n    {\n      \"id\": \"rivendell-031\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 31,\n      \"title\": \"Тропа вдоль ущелья\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 21,\n      \"from\": \"Восточные ущелья\",\n      \"to\": \"Брод Гремячей\",\n      \"segmentKm\": 9.4,\n      \"km\": 686.4,\n      \"steps\": 915200,\n      \"stepsSincePrevious\": 12533,\n      \"text\": \"Узкая тропа тянется по каменному карнизу над шумным потоком. На противоположной стене между выступами виднеются гнёзда горных птиц.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-031.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-031-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"rivendell-032\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 32,\n      \"title\": \"Крутой спуск\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 21,\n      \"from\": \"Восточные ущелья\",\n      \"to\": \"Брод Гремячей\",\n      \"segmentKm\": 18.8,\n      \"km\": 695.8,\n      \"steps\": 927733,\n      \"stepsSincePrevious\": 12533,\n      \"text\": \"Крутой спуск заставляет цепляться за выступы и тщательно выбирать каждый шаг. Внизу наконец появляется ровная площадка с видом на реку и далёкие холмы.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-032.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-032-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"rivendell-033\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 33,\n      \"title\": \"Берег Гремячей\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 21,\n      \"from\": \"Восточные ущелья\",\n      \"to\": \"Брод Гремячей\",\n      \"segmentKm\": 28.2,\n      \"km\": 705.2,\n      \"steps\": 940267,\n      \"stepsSincePrevious\": 12534,\n      \"text\": \"Гремячая встречает путешественника свежим речным ветром и негромким плеском о берег. Среди гладкой гальки находится голубоватый камешек, переливающийся на свету.\",\n      \"reward\": {\n        \"id\": \"rivendell-033-reward\",\n        \"name\": \"Речной самоцвет\",\n        \"kind\": \"Находка\",\n        \"icon\": \"❧\",\n        \"description\": \"\",\n        \"cardText\": \"Находка · Речной самоцвет\",\n        \"badgePrompt\": \"Гладкий маленький камень голубовато-зелёного цвета с тонкими светлыми прожилками, мокрый блеск речной гальки.\",\n        \"conditional\": false,\n        \"condition\": null\n      },\n      \"rewardSource\": \"Находка · Речной самоцвет\",\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": \"Гладкий маленький камень голубовато-зелёного цвета с тонкими светлыми прожилками, мокрый блеск речной гальки.\",\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-033.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-033-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"rivendell-034\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 34,\n      \"title\": \"След всадника\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 21,\n      \"from\": \"Восточные ущелья\",\n      \"to\": \"Брод Гремячей\",\n      \"segmentKm\": 37.6,\n      \"km\": 714.6,\n      \"steps\": 952800,\n      \"stepsSincePrevious\": 12533,\n      \"text\": \"Во влажном песке у реки отчётливо отпечатались свежие следы копыт. Самого всадника не видно, и только примятая трава подсказывает, куда он направился.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Проработать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-034.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-034-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"rivendell-035\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 35,\n      \"title\": \"Брод Гремячей\",\n      \"type\": \"Локация\",\n      \"segment\": 21,\n      \"from\": \"Восточные ущелья\",\n      \"to\": \"Брод Гремячей\",\n      \"segmentKm\": 47,\n      \"km\": 724,\n      \"steps\": 965333,\n      \"stepsSincePrevious\": 12533,\n      \"text\": \"Гремячая бурлит на каменистом броде, ставшем последней серьёзной преградой перед долиной. Вода холодна, но мелководье позволяет осторожно перейти на другой берег.\",\n      \"reward\": {\n        \"id\": \"rivendell-035-reward\",\n        \"name\": \"Последняя переправа\",\n        \"kind\": \"Достижение\",\n        \"icon\": \"✧\",\n        \"description\": \"\",\n        \"cardText\": \"Достижение · Последняя переправа\",\n        \"badgePrompt\": \"Небольшой серебряный значок с бурной рекой и простым каменным бродом, эмалевые голубые волны, гравированный край.\",\n        \"conditional\": false,\n        \"condition\": null\n      },\n      \"rewardSource\": \"Достижение · Последняя переправа\",\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": \"Небольшой серебряный значок с бурной рекой и простым каменным бродом, эмалевые голубые волны, гравированный край.\",\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-035.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-035-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": true\n    },\n    {\n      \"id\": \"rivendell-036\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 36,\n      \"title\": \"Тропа в долину\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 22,\n      \"from\": \"Брод Гремячей\",\n      \"to\": \"Ривенделл\",\n      \"segmentKm\": 4.33,\n      \"km\": 728.33,\n      \"steps\": 971107,\n      \"stepsSincePrevious\": 5774,\n      \"text\": \"По ту сторону брода тропа постепенно скрывается под зелёными сводами деревьев. Воздух становится мягче, а впереди всё отчётливее слышен шум водопада.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-036.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-036-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"rivendell-037\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 37,\n      \"title\": \"Еловая роща\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 22,\n      \"from\": \"Брод Гремячей\",\n      \"to\": \"Ривенделл\",\n      \"segmentKm\": 8.67,\n      \"km\": 732.67,\n      \"steps\": 976893,\n      \"stepsSincePrevious\": 5786,\n      \"text\": \"В еловой роще пахнет смолистой хвоей, а под ногами пружинит мягкая подстилка. Сквозь шелест ветвей вдруг пробиваются далёкие голоса и едва слышная музыка.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-037.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-037-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"rivendell-038\",\n      \"chapterId\": \"rivendell\",\n      \"order\": 38,\n      \"title\": \"Ривенделл\",\n      \"type\": \"Глава\",\n      \"segment\": 22,\n      \"from\": \"Брод Гремячей\",\n      \"to\": \"Ривенделл\",\n      \"segmentKm\": 13,\n      \"km\": 737,\n      \"steps\": 982667,\n      \"stepsSincePrevious\": 5774,\n      \"text\": \"Ривенделл открывается среди зелени, водопадов и светлых галерей, откуда доносятся песни эльфов. Здесь путника ждут гостеприимство Элронда, долгожданный отдых и памятная закладка из библиотеки.\",\n      \"reward\": {\n        \"id\": \"rivendell-038-reward\",\n        \"name\": \"Эльфийская закладка\",\n        \"kind\": \"Находка\",\n        \"icon\": \"❧\",\n        \"description\": \"\",\n        \"cardText\": \"Находка · Эльфийская закладка\",\n        \"badgePrompt\": \"Тонкая серебристая закладка с изящным ажурным листом и длинной цепочкой, утончённое эльфийское ремесло.\",\n        \"conditional\": false,\n        \"condition\": null\n      },\n      \"rewardSource\": \"Находка · Эльфийская закладка\",\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": \"Тонкая серебристая закладка с изящным ажурным листом и длинной цепочкой, утончённое эльфийское ремесло.\",\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/rivendell/rivendell-038.webp\",\n      \"thumbnail\": \"assets/illustrations/rivendell/rivendell-038-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": true\n    }\n  ]\n}");
